import {dishes,categories,experiences,wines} from './data.js';
import {state,money,esc,t,icon} from './state.js';
const photo=(name,alt,cls='')=>`<img class="${cls}" src="/assets/${name}.webp" alt="${alt}" loading="lazy" width="1200" height="900">`;
export function Header(){return `<header id="header"><a class="brand" href="/#inicio" aria-label="Aurelis, inicio">AURELIS<span>GRAND HOTEL</span></a><nav aria-label="Principal">${[['inicio','Inicio','Home'],['gastronomia','Gastronomía','Dining'],['carta','Carta','Menu'],['experiencias','Experiencias','Experiences'],['reservas','Reservas','Reservations'],['galeria','Galería','Gallery'],['hotel','Hotel','Hotel'],['contacto','Contacto','Contact']].map(([id,es,en])=>`<a href="/#${id}">${t(es,en)}</a>`).join('')}</nav><div class="header-actions"><button data-action="lang" class="language" aria-label="Cambiar idioma">${state.lang.toUpperCase()} <span>⌄</span></button><button class="icon-button" data-action="search" aria-label="Buscar platos">${icon('search')}</button><button class="icon-button profile-button" data-action="profile" aria-label="Mi perfil">${icon('user')}</button><button class="icon-button bag" data-action="cart" aria-label="Abrir pedido">${icon('bag')}<span class="badge">${state.cart.reduce((a,b)=>a+b.qty,0)}</span></button><button class="btn small header-reserve" data-action="reserve">${t('Reservar mesa','Book a table')}</button><button class="icon-button menu-toggle" data-action="menu" aria-label="Abrir menú">${icon('menu')}</button></div></header>`;}
export function Hero(){return `<section class="hero" id="inicio"><img class="hero-photo" src="/assets/hero.webp" alt="Wagyu de autor con trufa negra, hierbas y reducción de vino sobre vajilla artesanal" fetchpriority="high" width="1536" height="1024"><div class="hero-shade"></div><div class="hero-copy"><div class="eyebrow"><span></span> MAISON AURELIS · FINE DINING</div><h1>${t('Alta gastronomía,<br>elevada a una<br><em>experiencia.</em>','Fine dining,<br>elevated to an<br><em>experience.</em>')}</h1><p>${t('Descubra una cocina contemporánea creada alrededor del producto, la temporada y el arte de recibir.','Discover contemporary cuisine inspired by exceptional ingredients, the seasons, and the art of hospitality.')}</p><div class="button-row"><button class="btn" data-action="reserve">${t('Reservar una mesa','Book a table')} ${icon('arrow')}</button><a class="text-link" href="#carta">${t('Explorar la carta','Explore the menu')} ${icon('arrow')}</a></div></div><div class="hero-bottom"><span>MAISON AURELIS <i></i> FINE DINING <i></i> DINNER 18:30 — 23:30</span><a href="#gastronomia">${t('EL ARTE DE DISFRUTAR','THE ART OF ENJOYMENT')} <b>↓</b></a></div><div class="hero-caption"><span>MAISON SIGNATURE</span><div></div> WAGYU IMPERIAL</div></section>`;}
export function RestaurantIntro(){return `<section id="gastronomia" class="section intro"><div class="intro-photos">${photo('restaurant','Interior ficticio de Maison Aurelis, mesas íntimas y luz cálida')}<div class="inset">${photo('risotto','Risotto de autor con trufa negra')}<span>EL PRODUCTO. LA TÉCNICA. LA EMOCIÓN.</span></div></div><div class="intro-copy"><div class="eyebrow">01 — NUESTRA ESENCIA</div><h2>Maison <em>Aurelis</em></h2><p class="lead">Una interpretación contemporánea de la alta cocina donde ingredientes excepcionales, técnica y creatividad convergen en una experiencia diseñada para ser recordada.</p><p>Cada temporada abre una conversación distinta. La escuchamos, seleccionamos sus mejores ingredientes y dejamos que cada plato cuente su propia historia. El resto es el arte de recibir.</p><a href="#chef" class="text-link">${t('Conozca nuestra filosofía','Discover our philosophy')} ${icon('arrow')}</a><div class="facts"><div><strong>14</strong><span>Mesas, infinitas historias</span></div><div><strong>Contemporánea</strong><span>Cocina de temporada</span></div><div><strong>7 tiempos</strong><span>Menú degustación</span></div><div><strong>Privado</strong><span>Servicio a su medida</span></div></div></div></section>`;}
export function MenuCard(d){return `<article class="menu-card"><div class="card-image"><button class="image-open" data-action="product" data-id="${d.id}" aria-label="Ver detalles de ${d.name}"><img src="${d.image}" alt="${d.name}, presentación gastronómica ilustrativa" loading="lazy" width="600" height="450"></button><span class="dish-tag">${d.tags[0]}</span><button class="favorite ${state.favorites.includes(d.id)?'active':''}" data-action="favorite" data-id="${d.id}" aria-label="Favorito: ${d.name}" aria-pressed="${state.favorites.includes(d.id)}">${icon('heart')}</button></div><div class="card-title"><h3><button data-action="product" data-id="${d.id}">${d.name}</button></h3><span>${money(d.price)}</span></div><p>${d.description}</p><small>${t('Ingredientes','Ingredients')}: ${d.ingredients}</small><div class="card-bottom"><button data-action="product" data-id="${d.id}" class="details">${t('Ver detalles','View details')}</button><button class="add" data-action="add" data-id="${d.id}" ${!d.available?'disabled':''}>${d.available?t('Añadir al pedido','Add to order'):'No disponible'} <span>+</span></button></div></article>`;}
export function MenuCategories(){return `<section id="carta" class="section menu-section"><div class="section-heading"><div><div class="eyebrow">02 — UNA INVITACIÓN A DESCUBRIR</div><h2>${t('El arte de <em>elegir.</em>','The art of <em>choosing.</em>')}</h2></div><p>${t('Creaciones de temporada. Ingredientes extraordinarios.<br>Encuentre su próximo momento favorito.','Seasonal creations. Extraordinary ingredients.<br>Find your next favourite moment.')}</p></div><div class="menu-toolbar"><div class="menu-tabs" role="group" aria-label="Categorías">${['Todos',...categories].map(c=>`<button data-action="category" data-value="${c}" class="${c===state.category?'selected':''}">${c}</button>`).join('')}</div><div class="search-row"><label class="search-box">${icon('search')}<input id="dish-search" placeholder="${t('Buscar un plato, ingrediente…','Find a dish, ingredient…')}" value="${esc(state.search)}" aria-label="Buscar platos"></label><button class="filter-favorites ${state.favoritesOnly?'selected':''}" data-action="favorites">${icon('heart')} ${t('Mis favoritos','My favourites')}</button></div><div class="filters" role="group" aria-label="Filtros gastronómicos">${['Todos','Vegetariano','Vegano','Gluten Free','Seafood','Signature',"Chef's Selection"].map(f=>`<button data-action="filter" data-value="${f}" class="${f===state.filter?'selected':''}">${f}</button>`).join('')}</div></div><div id="menu-grid" class="menu-grid">${MenuResults()}</div><p class="allergen-note">${t('Por favor informe a nuestro equipo sobre cualquier alergia o restricción alimentaria antes de realizar su pedido.','Please tell our team about any allergies or dietary requirements before ordering.')} <span>Precios en soles · Servicio 10% calculado al finalizar.</span></p></section>`;}
export function MenuResults(){let list=dishes.filter(d=>d.category!=='Desayuno'&&(state.category==='Todos'||d.category===state.category)&&(state.filter==='Todos'||d.tags.includes(state.filter))&&(!state.favoritesOnly||state.favorites.includes(d.id))&&`${d.name} ${d.description} ${d.ingredients} ${d.tags.join(' ')}`.toLocaleLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'').includes(state.search.toLowerCase().normalize('NFD').replace(/\p{Diacritic}/gu,'')));return list.length?list.map(MenuCard).join(''):`<div class="empty"><h3>No encontramos platos</h3><p>Pruebe otra búsqueda o restablezca los filtros.</p><button class="btn outline" data-action="reset-filters">Ver toda la carta</button></div>`;}
export function Experiences(){return `<section id="experiencias" class="section experiences"><div class="section-heading"><div><div class="eyebrow">03 — MOMENTOS QUE PERMANECEN</div><h2>Experiencias <em>Aurelis</em></h2></div><p>El verdadero lujo es vivir algo<br>que ha sido pensado solo para usted.</p></div><div class="experience-grid">${experiences.map((e,i)=>`<button class="experience" data-action="experience" data-id="${e.id}">${photo(e.image,e.name)}<div class="experience-content"><span class="eyebrow">0${i+1} / EXPERIENCIAS PRIVADAS</span><h3>${e.name}</h3><p>${e.description}</p><div><span>Desde ${money(e.price)} <small>${e.unit}</small></span>${icon('arrow')}</div></div></button>`).join('')}</div></section>`;}
export function Reservations(){return `<section id="reservas" class="reservation-band"><div class="eyebrow">SU MESA LE ESPERA</div><h2>${t('Hagamos de esta noche<br>algo <em>extraordinario.</em>','Let’s make tonight<br><em>extraordinary.</em>')}</h2><p>Un espacio íntimo. Una atención que anticipa sus deseos.</p><button class="btn" data-action="reserve">${t('Consultar disponibilidad','Check availability')} ${icon('arrow')}</button><span class="fine-print">Martes a domingo · 18:30 — 23:30 · Hasta 8 invitados en reserva online</span></section>`;}
export function Chef(){return `<section id="chef" class="section chef-section"><div>${photo('chef','Retrato generado del personaje ficticio Chef Alexandre Beaumont')}</div><div><div class="eyebrow">LA VISIÓN DETRÁS DE CADA PLATO</div><h2>Alexandre<br><em>Beaumont</em></h2><blockquote>“Una visión gastronómica construida alrededor de precisión, producto y respeto por cada ingrediente.”</blockquote><p>Alexandre dirige la cocina de Maison Aurelis con una sensibilidad que une técnicas clásicas y una mirada contemporánea. En este universo ficticio, su trayectoria se inspira en los mercados de temporada, la hospitalidad y el trabajo artesanal.</p><p>Su filosofía es sencilla: intervenir con intención, servir con generosidad y permitir que el ingrediente conserve su voz.</p><span class="signature">Alexandre Beaumont</span><span class="eyebrow">CHEF EJECUTIVO · PERFIL FICTICIO</span></div></section>`;}
export function WineCellar(){return `<section id="bodega" class="section cellar"><div class="cellar-top"><div><div class="eyebrow">EL TIEMPO, SERVIDO EN UNA COPA</div><h2>The <em>Cellar</em></h2><p>Una colección para acompañar conversaciones.<br>Descubra la selección de nuestro sommelier.</p></div>${photo('wine','Copa de vino tinto en la bodega ficticia Aurelis')}</div><div class="wine-tabs filters">${['Todos','Champagne','Francia','Italia','España','Argentina','Chile','Selección del Sommelier'].map((c,i)=>`<button data-action="wine-filter" data-value="${c}" class="${!i?'selected':''}">${c}</button>`).join('')}</div><div id="wine-list">${WineRows()}</div><div class="sommelier"><div><div class="eyebrow">SOMMELIER DIGITAL</div><h3>Encuentre el maridaje perfecto.</h3><label for="pairing">Seleccione su plato</label><select id="pairing">${dishes.filter(d=>d.id<=17).map(d=>`<option value="${d.id}" ${d.id===9?'selected':''}>${d.name}</option>`).join('')}</select></div><div id="pairing-result">${Pairing(9)}</div></div><p class="fine-print">Todas las etiquetas, añadas y recomendaciones son ficticias para esta demostración. Servicio de bebidas alcohólicas para mayores de 18 años.</p></section>`;}
export function WineRows(category='Todos'){return wines.filter(w=>category==='Todos'||category==='Selección del Sommelier'&&[0,1,6].includes(w.id)||w.region===category).map(w=>`<article class="wine-row"><div><h3>${w.name} <em>${w.year}</em></h3><p>${w.region} · ${w.notes}</p></div><div><span>Copa <strong>${money(w.glass)}</strong></span><span>Botella <strong>${money(w.bottle)}</strong></span></div></article>`).join('');}
export function Pairing(id){const d=dishes.find(x=>x.id===Number(id));const w=wines[['Tierra'].includes(d.category)?0:['Mar','Entradas'].includes(d.category)?6:d.category==='Postres'?1:5];return `<span class="eyebrow">NUESTRA RECOMENDACIÓN</span><h3>${w.name} ${w.year}</h3><p>${w.notes} ${d.category==='Tierra'?'Sus taninos estructurados complementan la intensidad del plato.':'Un equilibrio que realza los matices y la textura del plato.'}</p><span>${money(w.glass)} / copa</span>`;}
export function Gallery(){return `<section id="galeria" class="section gallery-section"><div class="section-heading"><div><div class="eyebrow">UN UNIVERSO DE SENSACIONES</div><h2>Instantes <em>Aurelis</em></h2></div><p>Hay momentos que comienzan con una mirada.</p></div><div class="gallery">${[['hero','El arte en el plato'],['restaurant','El arte de recibir'],['dessert','El último recuerdo'],['cocktail','Después del anochecer'],['chef','Precisión y pasión'],['wine','Una pausa, una copa'],['lobster','Esencia del mar'],['breakfast','Mañanas sin prisa'],['restaurant','Su celebración privada']].map(([im,alt],i)=>`<button class="gallery-item g${i}" data-action="gallery" data-image="${im}" data-title="${alt}">${photo(im,alt)}<span>${alt} ↗</span></button>`).join('')}</div></section>`;}
export function RoomServiceTeaser(){return `<section class="room-teaser"><div>${photo('breakfast','Desayuno en habitación de Aurelis')}</div><div><div class="eyebrow">EL PRIVILEGIO DE QUEDARSE</div><h2>Private Dining.<br><em>Delivered to your room.</em></h2><p>El sabor de Maison Aurelis, en la intimidad de su suite. Desde el primer café hasta el último antojo de la noche.</p><a class="text-link" href="/room-service">Explorar Room Service ${icon('arrow')}</a><button class="text-link" data-action="breakfast">Programar desayuno en habitación ${icon('arrow')}</button></div></section>`;}
export function RoomService(){return `<main id="main"><section class="room-hero">${photo('breakfast','Bandeja de desayuno gourmet')}<div><a href="/" class="eyebrow">AURELIS GRAND HOTEL / ROOM SERVICE</a><h1>Private Dining.<br><em>Delivered to your room.</em></h1><p>El arte de recibir, en la privacidad de su suite.</p><label>Número de habitación<input id="room-number" placeholder="Ej. 508" inputmode="numeric" maxlength="6"></label><button class="btn" data-action="breakfast">Programar desayuno</button></div></section><section class="section"><div class="section-heading"><h2>At your <em>service.</em></h2><p>Disponibilidad simulada · Entrega estimada 35–45 min</p></div><div class="filters room-tabs">${['Breakfast','All Day','Dinner','Desserts','Drinks','Late Night'].map((x,i)=>`<button class="${!i?'selected':''}" data-action="room-category" data-value="${x}">${x}</button>`).join('')}</div><div class="menu-grid" id="room-grid">${RoomResults('Breakfast')}</div></section></main>`;}
export function RoomResults(c){return dishes.filter(d=>c==='Breakfast'?d.category==='Desayuno':c==='Desserts'?d.category==='Postres':c==='Drinks'?['Bebidas','Cócteles','Café & Té'].includes(d.category):c==='Late Night'?[12,16,18,20].includes(d.id):c==='Dinner'?['Tierra','Mar','Pastas'].includes(d.category):['Entradas','Pastas','Vegetarianos'].includes(d.category)).map(MenuCard).join('');}
export function PrivateEvents(){return `<section id="eventos" class="section event-section"><div class="eyebrow">UN ESCENARIO A LA ALTURA</div><h2>Private <em>Events</em></h2><p>Cenas empresariales, bodas íntimas, aniversarios y celebraciones privadas.<br>Del primer detalle al último brindis, nosotros nos encargamos.</p><button class="btn outline" data-action="event">Planificar un evento ${icon('arrow')}</button></section>`;}
export function Hotel(){return `<section id="hotel" class="section hotel"><div class="eyebrow">MÁS ALLÁ DE LA MESA</div><h2>El universo <em>Aurelis</em></h2><div class="hotel-links">${['Suites','Spa','Wellness','Rooftop','Concierge','Gastronomía','Private Events'].map((s,i)=>`<button data-action="hotel" data-value="${s}"><span>0${i+1}</span>${s}${icon('arrow')}</button>`).join('')}</div></section>`;}
export function Testimonials(){return `<section class="section testimonials"><div class="eyebrow">RECUERDOS DE NUESTROS HUÉSPEDES</div><div class="testimonial-grid">${[['Una experiencia ejecutada con precisión desde el primer servicio hasta el último postre.','Huésped internacional'],['La intimidad, los sabores y cada pequeño detalle hicieron de nuestra celebración algo inolvidable.','Cena de aniversario'],['Un servicio que entiende el valor de la discreción. La elección perfecta para una cena de negocios.','Huésped ejecutivo']].map(([q,n])=>`<figure><span class="quote">“</span><blockquote>${q}</blockquote><figcaption>— ${n}</figcaption></figure>`).join('')}</div><p class="fine-print">Testimonios ficticios creados para este proyecto conceptual.</p></section>`;}
export function FinalCTA(){return `<section class="final-cta">${photo('restaurant','Ambiente nocturno de Maison Aurelis')}<div><div class="eyebrow">SU PRÓXIMO RECUERDO COMIENZA AQUÍ</div><h2>An evening<br><em>worth remembering.</em></h2><p>Permita que nuestro equipo prepare una experiencia<br>diseñada especialmente para usted.</p><div class="button-row"><button class="btn" data-action="reserve">Reservar mesa</button><button class="btn outline" data-action="concierge">Contactar Concierge</button></div></div></section>`;}
export function Footer(){return `<footer id="contacto"><div class="footer-top"><div><a class="brand" href="/">AURELIS<span>GRAND HOTEL</span></a><p>El arte de crear recuerdos.</p><p class="fine-print">+51 900 000 000 — Demo<br>concierge@aurelis.example<br>Destino e identidad completamente ficticios.</p></div><div><h4>Aurelis</h4>${['Hotel','Suites','Gastronomía','Wellness','Experiences'].map(s=>`<button data-action="hotel" data-value="${s}">${s}</button>`).join('')}</div><div><h4>Maison Aurelis</h4><a href="/#carta">Carta</a><button data-action="reserve">Reservas</button><button data-action="experience" data-id="private">Private Dining</button><a href="/room-service">Room Service</a><button data-action="event">Eventos</button></div><div><h4>Información</h4>${['Contacto','Preguntas frecuentes','Privacidad','Términos'].map(s=>`<button data-action="info" data-value="${s}">${s}</button>`).join('')}</div><div><h4>Encuéntrenos</h4>${['Instagram','Facebook','LinkedIn'].map(s=>`<button data-action="social" data-value="${s}">${s} ↗</button>`).join('')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} AURELIS GRAND HOTEL</span><span>Concept project / Demo experience.</span><a href="#inicio">VOLVER ARRIBA ↑</a></div></footer><button class="concierge-float" data-action="concierge">${icon('chat')} Concierge</button><nav class="mobile-bottom" aria-label="Navegación móvil"><a href="/">Inicio</a><a href="/#carta">Carta</a><button data-action="reserve">Reservar</button><button data-action="cart">Pedidos <span class="mobile-count"></span></button><button data-action="profile">Perfil</button></nav>`;}
